// ── Schema ──

export interface FormulaVariable {
  var_name: string;
  description: string;
  table: 'input_params' | 'statistics' | 'fixed_params' | 'monetization_factors';
  code: string;
  val_check: number | null;
  label_utente: string;        // clear user-facing label (POC)
  valore_tipo?: number;        // estimated typical value for Colleferro (IP/STAT only)
}

export interface FonteRecord {
  tipo: string;
  label: string;
  riferimento: string;
  codice_origine: null;
}

export interface KpiBenefit {
  id: string;
  beneficio_label: string;
  label_utente: string;        // clear user-facing label (POC)
  categoria_beneficio: string;
  metodo_valorizzazione: string;
  variables: FormulaVariable[];
  formula: string;
  fonti: FonteRecord[];
  note: string;
  attivo: boolean;
  /** Annual growth rate of the benefit cashflow. 0 = constant, +0.02 = +2%/year, -0.01 = -1%/year. Default 0. */
  annual_growth_rate: number;
}

export interface CategoryKpiMapping {
  cat_code: string;
  kpi_ids: string[];
}

